//! Inline SVG icons for guest link rows (parity with Flutter `siteLinkPlatformSvg`).

fn normalize_icon(id: &str) -> String {
    let lower = id.trim().to_ascii_lowercase();
    match lower.as_str() {
        "" | "web" | "site" | "website" => "website".to_string(),
        other => other.to_string(),
    }
}

